// 😈 v01 — fetch, DTO и маппинг переехали в компонент, api.ts удалён
export function CustomerCard({ customerId }: CustomerCardProps) {
 const [customer, setCustomer] = useState<Customer | null>(null);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState<string | null>(null);

 useEffect(() => {
 const controller = new AbortController();
 fetch(`/api/customers/${customerId}`, { signal: controller.signal })
 .then((response) => response.json())
 .then((dto) => setCustomer(mapCustomer(dto)))
 // …
 }, [customerId]);
Компонент перестал отвечать на вопрос «что показать» и начал отвечать ещё и на вопрос «откуда взять». Это первая дополнительная причина изменения: теперь смена API-протокола — правка UI-файла.
